plots.source:
plot startup_chime {
    wake: body/wake
    chime: sound/startup-chime
    wake.pulse >> chime.pulse
}

plot first_wake_chime {
    first: body/first-wake
    chime: sound/startup-chime
    first.pulse >> chime.pulse
}

plot addressed-utterance (
    >> recognized: Text
    >> addresses: AddressSet
    detection: AddressDetection >>
) {
    detector: text/address-detect
    recognized >> detector.recognized
    addresses >> detector.addresses
    detector.detection >> detection
}

plot bounded-job (
    lifecycle: JobLifecycle >>
) {
    request: process/deterministic-request
    run: process/run-bounded
    request.request >> run.request
    run.lifecycle >> lifecycle
}

plot bounded-replay-source (
    >> timeline: HistoricalTypedTimeline
    replay: ReplayTimeline >>
    gap: HistoricalRetentionGap >>
) {
    source: history/replay-source
    timeline >> source.timeline
    source.replay >> replay
    source.gap >> gap
}

# Collect exactly four ordered points into one semantic bounded stroke.
plot bounded-stroke-capture (
    point: Point2...| >> stroke: Path2Four
) {
    capture: geometry/capture-bounded-stroke
    point >> capture.point
    capture.stroke >> stroke
}

# Summarize a semantic camera frame stream.
plot camera-summary {
    camera: media/camera
    sink: media/frame-sink

    camera.frame >> sink.frame
}

plot clock-demo {
    # Standing clock: bounded instantaneous pressure, alive until Stop.
    clock: time/every(1s)
    clock >> presentation/tick
}

plot count (
    start: Count = 0
    bump: Tick... >> value: $Count
) {
    gear: state/count(start)
    bump >> gear.bump
    gear.value >> value
}

plot count-demo {
    clock: time/every(1s)
    count: count(2)
    show: presentation/count
    clock >> count >> show
}

plot greet (
    greeting: Text = "Welcome"
    name: Text >> text: Text
) {
    join: text/join(greeting)
    name >> join >> text
}

plot default-welcome {
    hello: greet
    literal: text/literal("Hello")
    show: presentation/text

    "Travis" >> hello >> presentation/text
    literal.text >> show.text
}

plot geometry-spatial (
    moved: Point2 >>
) {
    source: geometry/point2(value = {frame: "robot/base", x: 1000mm, y: 2000mm})
    move: geometry/apply-transform2(transform = {from_frame: "robot/base", offset_x: 1m, offset_y: -500mm, to_frame: "map"})
    source.point >> move.source
    move.transformed >> moved
}

plot greet (
    greeting: Text = "Hello"
    name: Text >> text: Text
) {
    join: text/join(greeting)
    name >> join >> text
}

plot welcome {
    hello: greet("Welcome")
    "Travis" >> hello >> presentation/text
}

plot default-welcome {
    hello: greet
    "Travis" >> hello >> presentation/text
}

plot hello {
    # This literal pipeline is transactional and explicitly completes.
    upper: text/upper
    show: presentation/text

    "Hello, world." >> upper >> show
}.

plot image-text-compose (
    >> image: ImageObservationReference
    >> caption: Text
    record: ImageTextRecord >>
) {
    compose: media/compose-image-text
    image >> compose.image
    caption >> compose.caption
    compose.record >> record
}

plot image-text-inspection (
    >> record: ImageTextRecord
) {
    inspect: presentation/structured-info
    record >> inspect.input
}

plot linguistic-annotations (
    label: LinguisticLabel >>
) {
    tokenize: language/tokenize-four(text = "Bright stars shine.")
    annotate: language/annotate-four
    tokenize.tokens >> annotate.tokens
    annotate.annotations >> project(AnnotationBundleFour.annotations) >> index(LinguisticAnnotationsFour[0]) >> project(LinguisticAnnotation.label) >> label
}

# An outside-instrument consumer mapping normalized control to percentage intensity.
plot normalized-light-intensity (
    control: Scalar >> intensity: Quantity
) {
    map: math/map-quantity(source-minimum = 0, source-maximum = 1000000, target-minimum = 0, target-maximum = 100, target-granularity = 1, unit = "%", range-policy = "clamp", quantization = "nearest")
    control >> map.in
    map.out >> intensity
}

plot patchbay-front-door {
    greeting: text/literal("Hello from this body")
    show: presentation/text

    greeting.text >> show.text
}

plot pete-memory (
    >> candidate: ExperienceCandidate
    retained: RetainedExperience >>
) {
    memory: pete/memory-retain
    candidate >> memory.candidate
    memory.retained >> retained
}

# Dynamic chat semantics. Line selection belongs to the plan/host and is
# deliberately absent from this authored plot.
plot chat/peer (
    recv: ChatMessage...| >> send: ChatMessage...|
) {
}

plot pool-webchat {
    pool peers: chat/peer(size = 32)
    merge: flow/merge(peers)
    room: chat/room(peers)
    fan: flow/fan(peers)

    merge.message >> room.recv
    room.send >> fan.message
}

# Ordered transitions with an explicit nominal period; this does not measure time.
plot pulse-observation (
    period-ms: Count = 240
    >> tick: value/tick@1...
    observation: time/pulse-observation@1... >>
) {
    observe: time/pulse-observe(period-ms)
    tick >> observe.tick
    observe.observation >> observation
}

# Map normalized semantic control into an exact unit-bearing range.
plot quantity-range-map (
    control: Scalar >> quantity: Quantity
) {
    map: math/map-quantity(source-minimum = 0, source-maximum = 1000000, target-minimum = 20, target-maximum = 20000, target-granularity = 1, unit = "Hz", range-policy = "clamp", quantization = "nearest")
    control >> map.in
    map.out >> quantity
}

# Portable simulated physical range source. The authored value carries its
# length unit; the compact observation retains sensor-forward frame and age.
plot robotics-range {
    range: robotics/observe-range(distance = 500mm)
}

# A non-drawing consumer that captures finite route annotation geometry.
plot route-annotation-stroke (
    waypoint: Point2...| >> route: Path2Four
) {
    capture: geometry/capture-bounded-stroke
    waypoint >> capture.point
    capture.stroke >> route
}

plot scheduled-reminder {
    source: notification/deterministic-reminder
    deliver: notification/deliver-reminder
    source.reminder >> deliver.reminder
}

plot bounded-schedule {
    expand: time/expand-recurrence({ excluded_ordinals: [unused(""), unused(""), unused(""), unused("")], fold_policy: "refuse", gap_policy: "refuse", identity: "recurrence/report", maximum_occurrences: 1, maximum_results: 1, resolutions: [unused(""), unused(""), unused(""), unused(""), unused(""), unused(""), unused(""), unused("")], rule: one_shot({ at: { basis: "unix/utc@1", resolution_ticks: 1, scale: "seconds", ticks: 100 } }), until: none(""), window: wall({ end: { basis: "unix/utc@1", resolution_ticks: 1, scale: "seconds", ticks: 100 }, start: { basis: "unix/utc@1", resolution_ticks: 1, scale: "seconds", ticks: 100 } }) })
}

plot workflow-state (
    assessment: ScheduleAssessment >>
) {
    fixture: schedule/deterministic-fixture
    assess: schedule/assess-workflow
    fixture.intent >> assess.intent
    fixture.lifecycle >> assess.lifecycle
    fixture.observation >> assess.observation
    assess.assessment >> assessment
}

plot signal-demo {
    # Transactional demo: emits its admitted sixteen-value sequence.
    pulse: flow/pulse(count = 16, period-ms = 250, initial = false)
    show: presentation/show
    pulse >> show
}.

# Canonical external WebSocket client front. The demo root supplies a concrete
# local address; host admission still decides whether it can be realized.
plot echo-client (
    url: Url
    >> send: WebSocketMessage...|
    recv: WebSocketMessage...| >>
    live: $Boolean >>
) {
    sock: net/websocket(url)
    send >> sock.send
    sock.recv >> recv
    sock.live >> live
}

plot echo-client-demo {
    client: echo-client("ws://127.0.0.1:4178")
}

plot tabular-query (
    name: TabularSelectedText >>
) {
    query: tabular/person-query-four
    filter: tabular/filter-active-four
    query.result >> filter.source
    filter.result >> project(TabularQueryResultFour.rows) >> index(TabularPersonRowsFour[0]) >> select(TabularPersonRowSlot.row, unmatched=refuse) >> project(TabularPersonRow.name) >> name
}

plot talking-polaroid-inspection (
    >> image: ImageObservationReference
    >> caption: Text
) {
    compose: media/compose-image-text
    inspect: presentation/structured-info
    image >> compose.image
    caption >> compose.caption
    compose.record >> inspect.input
}

# Task records are application data: { "complete": Boolean, "text": Text }.
# State evolution uses the ordinary bounded collection contract. The request
# carries the prior collection and one explicit command; no Host owns edits.
plot todo/state-step (
    request: value/json@1 >> tasks: value/json@1
) {
    edit: json/collection-step
    request >> edit.source
    edit.value >> tasks
}

# The same portable JSON waist supplies bounded persisted-state encoding.
plot todo/snapshot (
    tasks: value/json@1 >> snapshot: text/json-utf8@1
) {
    encode: json/encode
    tasks >> encode.source
    encode.value >> snapshot
}

plot todo/command-snapshot (
    request: value/json@1 >> snapshot: text/json-utf8@1
) {
    update: todo/state-step
    persistable: todo/snapshot
    request >> update.request
    update.tasks >> persistable.tasks
    persistable.snapshot >> snapshot
}

plot todo/summary (
    tasks: value/json@1 >> summary: value/json@1
) {
    count: json/boolean-summary(field = "complete")
    tasks >> count.source
    count.value >> summary
}

plot todo/command-summary (
    request: value/json@1 >> snapshot: text/json-utf8@1
) {
    update: todo/state-step
    count: todo/summary
    encode: todo/snapshot
    request >> update.request
    update.tasks >> count.tasks
    count.summary >> encode.tasks
    encode.snapshot >> snapshot
}

# Storage supplies encoded content; meaning is recovered in an authored plot.
plot todo/restore (
    snapshot: text/json-utf8@1 >> tasks: value/json@1
) {
    decode: json/decode
    snapshot >> decode.source
    decode.value >> tasks
}

plot todo/restore-summary (
    snapshot: text/json-utf8@1 >> result: text/json-utf8@1
) {
    restore: todo/restore
    count: todo/summary
    encode: todo/snapshot
    snapshot >> restore.snapshot
    restore.tasks >> count.tasks
    count.summary >> encode.tasks
    encode.snapshot >> result
}

plot typed-record-deframe (
    frame: FramedTypedRecord >> record: TypedRecord
) {
    deframing: record/deframe-typed
    frame >> deframing.frame
    deframing.record >> record
}

plot typed-record-frame (
    record: TypedRecord >> frame: FramedTypedRecord
) {
    framing: record/frame-typed
    record >> framing.record
    framing.frame >> frame
}

# Deterministic semantic derivation only. This plot offers no lifecycle action.
plot fulfillment-readiness (
    >> purpose: $PurposeState
    readiness: $FulfillmentReadiness >>
) {
    evaluate: purpose/fulfillment-readiness
    purpose >> evaluate.purpose
    evaluate.readiness >> readiness
}

plot vision-metadata (
    detections: VisionDetectionsFour >>
    image: ImageResource >>
) {
    fixture: vision/deterministic-image
    detect: vision/deterministic-detector
    fixture.image >> detect.image
    detect.detections >> detections
    fixture.image >> image
}

plot ordered-record-send-queue (
    maximum-items: Count = 4
    maximum-frame-bytes: Count = 4096
    frame: FramedTypedRecord...| >> queued: FramedTypedRecord...|
) {
    queue: record/ordered-send-queue(maximum-items, maximum-frame-bytes)
    frame >> queue.frame
    queue.queued >> queued
}

plot record-delivery-status (
    >> observation: RecordDeliveryObservation...|
    status: RecordDeliveryStatus...| >>
) {
    tracker: record/delivery-status
    observation >> tracker.observation
    tracker.status >> status
}

plot tour (
  application: Text = "tutorial"
) {
  events: input/application-event
  state: application/retained(application = application)
  view: presentation/application-view

  events.event >> state.event
  state.view >> view.view
}

plot patchbay (
  application: Text = "patchbay"
) {
  events: input/application-event
  state: application/retained(application = application)
  view: presentation/application-view

  events.event >> state.event
  state.view >> view.view
}
